// Rapikan Data Tweet (Code, Run Once for All Items)
// Hasil node Pengambil Data (Xpoz MCP) berupa teks. Kode ini memecahnya
// menjadi satu item per tweet: id, text, penulis, waktu pengambilan.
// Format teks yang didukung:
//   1) JSON biasa
//   2) TOON tabel   : results[10]{id,text,authorUsername,...}:  lalu 10 baris nilai
//   3) TOON daftar  : results[2]:  lalu blok "- id: ..." (dipakai bila kolom antar tweet tidak seragam)
//   4) hasil kosong : results: []  atau  results[0]...  (workflow berhenti tanpa error)

const waktuAmbil = DateTime.now().setZone('Asia/Jakarta').toFormat('yyyy-MM-dd HH:mm:ss');

// ---------- JSON: cari array tweet (objek yang punya "id" DAN "text") ----------
let adaStrukturKosong = false;
function cariTweet(node, depth = 0) {
  if (Array.isArray(node)) {
    if (node.length && node[0] && typeof node[0] === 'object' && ('id' in node[0]) && ('text' in node[0])) return node;
    for (const v of node) { const r = cariTweet(v, depth + 1); if (r) return r; }
    return null;
  }
  if (node && typeof node === 'object' && depth < 6) {
    for (const key of ['results', 'data', 'posts', 'items', 'tweets']) {
      if (Array.isArray(node[key]) && node[key].length === 0) { adaStrukturKosong = true; }
    }
    for (const v of Object.values(node)) { const r = cariTweet(v, depth + 1); if (r) return r; }
  }
  return null;
}

// ---------- nilai TOON: bertanda kutip (dengan escape) atau polos ----------
function bacaKutip(s, i) {            // s[i] adalah tanda kutip pembuka; kembalikan [nilai, indeksSesudahKutipPenutup]
  let v = '';
  i++;
  while (i < s.length) {
    const ch = s[i];
    if (ch === '\\') {
      const nx = s[i + 1];
      v += nx === 'n' ? '\n' : nx === 't' ? '\t' : nx === 'r' ? '\r' : nx;
      i += 2; continue;
    }
    if (ch === '"') { i++; break; }
    v += ch; i++;
  }
  return [v, i];
}
const bersih = (v) => (v === 'null' ? '' : v);

// ---------- TOON tabel ----------
function parseTabel(text) {
  const hasil = [];
  const re = /(\w+)\[(\d+)([|\t]?)\]\{([^}]*)\}:/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    const pemisah = m[3] === '|' ? '|' : (m[3] === '\t' ? '\t' : ',');
    const kolom = m[4].split(/[,|\t]/).map(s => s.trim());   // nama kolom tidak pernah memuat pemisah
    const jumlah = parseInt(m[2], 10);
    let i = re.lastIndex;
    for (let r = 0; r < jumlah; r++) {
      while (i < text.length && /[ \t\r\n]/.test(text[i]) && text[i] !== pemisah) i++;
      if (i >= text.length) break;
      const nilai = [];
      for (let c = 0; c < kolom.length; c++) {
        let v = '';
        if (text[i] === '"') { [v, i] = bacaKutip(text, i); }
        else {
          while (i < text.length && text[i] !== pemisah && text[i] !== '\n') { v += text[i]; i++; }
          v = bersih(v.trim());
        }
        nilai.push(v);
        if (text[i] === pemisah) i++;
      }
      const obj = {};
      kolom.forEach((k, idx) => { obj[k] = nilai[idx]; });
      hasil.push(obj);
    }
    re.lastIndex = i;
  }
  return hasil;
}

// ---------- TOON daftar ----------
function parseDaftar(text) {
  const hasil = [];
  const baris = text.split('\n');
  for (let b = 0; b < baris.length; b++) {
    const h = baris[b].match(/^(\s*)(\w+)\[(\d+)[|\t]?\]:\s*$/);          // judul array tanpa kurung kurawal
    if (!h) continue;
    const indentJudul = h[1].length;
    let obj = null;
    for (b = b + 1; b < baris.length; b++) {
      const ln = baris[b];
      if (!ln.trim()) continue;
      const indent = ln.match(/^\s*/)[0].length;
      if (indent <= indentJudul) { b--; break; }                           // array selesai
      let isi = ln.trim();
      if (isi.startsWith('- ')) { if (obj) hasil.push(obj); obj = {}; isi = isi.slice(2); }
      if (!obj) continue;
      const kv = isi.match(/^(\w+)(?:\[\d+[|\t]?\])?:\s*(.*)$/);
      if (!kv) continue;
      let v = kv[2];
      if (v.startsWith('"')) { [v] = bacaKutip(v, 0); } else { v = bersih(v.trim()); }
      obj[kv[1]] = v;
    }
    if (obj) hasil.push(obj);
  }
  return hasil.filter(o => 'id' in o && 'text' in o);
}

// ---------- baca semua hasil node sebelumnya ----------
const semua = [];
let teksSemua = '';
for (const item of $input.all()) {
  const sumber = [];
  if (item.json.structuredContent) sumber.push(item.json.structuredContent);
  for (const c of (item.json.content || [])) {
    if (!c || typeof c.text !== 'string') continue;
    teksSemua += c.text + '\n';
    if (item.json.isError) throw new Error('Xpoz mengembalikan error: ' + c.text.slice(0, 300));
    let json = null;
    try { json = JSON.parse(c.text); } catch (e) { /* bukan JSON */ }
    if (json !== null) { sumber.push(json); continue; }
    const tabel = parseTabel(c.text);
    semua.push(...(tabel.length ? tabel : parseDaftar(c.text)));
  }
  for (const s of sumber) { const r = cariTweet(s); if (r) semua.push(...r); }
}

if (semua.length === 0) {
  // hasil kosong yang sah: JSON kosong, "results: []", atau "results[0]"
  if (adaStrukturKosong || /\w+\s*:\s*\[\s*\]/.test(teksSemua) || /\w+\[0[|\t]?\]/.test(teksSemua)) return [];
  throw new Error('Format hasil Xpoz tidak dikenali. Cuplikan: ' + (teksSemua || JSON.stringify($input.first().json)).slice(0, 300));
}

// ---------- satu item per tweet ----------
const dilihat = new Set();
const out = [];
for (const t of semua) {
  const idTweet = String(t.id || '');
  const teks = String(t.text || '').replace(/\s+/g, ' ').trim();
  if (!idTweet || !teks || dilihat.has(idTweet)) continue;            // buang kosong dan duplikat
  dilihat.add(idTweet);
  out.push({ json: { id: idTweet, text: teks, penulis: bersih(String(t.authorUsername || '')), waktu: waktuAmbil } });
}
return out;

