// Analisis Data (Code, Run Once for All Items)
// Menghitung total tweet, jumlah per sentimen, dan persentase dominasi
// dari data pada sheet "Data Mentah".

const WINDOW_HOURS = 24;                       // hanya data 24 jam terakhir
const rows = $input.all().map(i => i.json).filter(r => r && r.Sentiment);
const now = DateTime.now().setZone('Asia/Jakarta');

function parseWaktu(v) {
  if (!v) return null;
  let d = DateTime.fromFormat(String(v), 'yyyy-MM-dd HH:mm:ss', { zone: 'Asia/Jakarta' });
  if (!d.isValid) d = DateTime.fromISO(String(v), { zone: 'Asia/Jakarta' });
  return d.isValid ? d : null;
}

let periode = '24 jam terakhir';
let terpilih = rows.filter(r => {
  const d = parseWaktu(r.Waktu);
  return !d || now.diff(d, 'hours').hours <= WINDOW_HOURS;   // baris tanpa waktu valid tetap dihitung
});
if (terpilih.length === 0 && rows.length > 0) {
  terpilih = rows;
  periode = 'seluruh data tersimpan (tidak ada data 24 jam terakhir)';
}

let positive = 0, negative = 0, neutral = 0;
for (const r of terpilih) {
  const s = String(r.Sentiment).trim().toLowerCase();
  if (s === 'positive') positive++;
  else if (s === 'negative') negative++;
  else if (s === 'neutral') neutral++;
}
const total = positive + negative + neutral;

const persen = (n) => (total ? Math.round((n / total) * 1000) / 10 : 0);
const hitung = [
  { label: 'Positif', n: positive },
  { label: 'Negatif', n: negative },
  { label: 'Netral', n: neutral }
].sort((a, b) => b.n - a.n);

let dominan = 'Tidak ada data';
let persenDominan = 0;
if (total > 0) {
  if (hitung[0].n === hitung[1].n) {          // dua kategori teratas sama besar
    dominan = 'Seimbang';
    persenDominan = persen(hitung[0].n);
  } else {
    dominan = hitung[0].label;
    persenDominan = persen(hitung[0].n);
  }
}

return [{
  json: {
    periode: periode,
    total_tweets: total,
    sentimen_positif: positive,
    sentimen_negatif: negative,
    sentimen_netral: neutral,
    persen_positif: persen(positive),
    persen_negatif: persen(negative),
    persen_netral: persen(neutral),
    dominan: dominan,
    persen_dominan: persenDominan
  }
}];

